-- PowerKing Turbo Power PK-60 120W Fast Charger
insert into public.products (
  sku, name, slug, description, brand_id, category_id, product_image,
  gallery_images, units_per_carton, cost_price, wholesale_price,
  retail_price, carton_price, minimum_order_quantity, low_stock_threshold,
  is_active, is_featured, tags
) select
  'PK-60', 'PowerKing Turbo Power PK-60 120W Fast Charger', 'powerking-turbo-power-pk-60-120w', 'All-protocol 120W wall charger with a single USB-A port, supplied with a 100cm USB-A to Type-C cable. Input 110-220V; output 5V/3A, 9V/2.77A or 12V/2.08A. Carries overcurrent, overvoltage, short-circuit and temperature protection, and supports Turbo Charge, Super Fast, Dash, Flash Charge, Warp, SuperVOOC and Quick Charge 4.0 handsets.',
  (select id from public.brands where slug = 'powerking'),
  (select id from public.categories where slug = 'chargers-adapters'),
  '/images/products/powerking-turbo-power-pk-60-120w.png', '{}', 1,
  0, 0, 0, NULL,
  1, 10, true, true, ARRAY['fast charger', '120w', 'usb a', 'type c', 'turbo', 'quick charge', 'all protocol', '6938473487001']::text[]
where not exists (
  select 1 from public.products where slug = 'powerking-turbo-power-pk-60-120w' or lower(sku) = lower('PK-60')
);

