-- ------------------------------------------------------- inventory ----
-- One stock row per product at the default location, all at zero. It has
-- to exist before the first stock-in so the inventory screens have
-- something to list; record_stock_movement() would create it anyway.
insert into public.inventory (product_id, location_id, quantity)
select p.id, l.id, 0
from public.products p
cross join (select id from public.inventory_locations where is_default limit 1) l
on conflict (product_id, location_id) do nothing;

commit;
